/** Accept only bounded, inline JPEGs generated by our media pipeline. */
export function validMicroPreview(value: unknown): string | undefined {
  if (typeof value !== "string" || value.length > 8192) return;
  return /^data:image\/jpeg;base64,\/9j\/[A-Za-z0-9+/]*={0,2}$/.test(value) ? value : undefined;
}
